<script setup>import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';import CustomerShell from '../../Components/CustomerShell.vue';const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),form=useForm({name:'',email:'',phone:'',password:'',password_confirmation:'',turnstile_token:''});const submit=()=>{if(form.processing)return;form.post('/register',{onFinish:()=>{form.reset('password','password_confirmation');form.turnstile_token='';turnstile.value?.reset()}})};</script>
<template><Head title="Daftar"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">Buat akun</p><h1>Daftar LFAMILIA</h1><p>Buat akun untuk saldo, riwayat pesanan, membership, dan layanan pelanggan.</p><div class="grid gap-3"><label v-for="x in [{k:'name',l:'Nama',t:'text',a:'name',p:'Masukkan nama'},{k:'email',l:'Email',t:'email',a:'email',p:'Masukkan email'},{k:'phone',l:'Nomor WhatsApp',t:'tel',a:'tel',p:'Contoh: 081234567890'}]" :key="x.k" class="text-[10px] font-semibold text-white/70">{{x.l}}<input v-model="form[x.k]" :type="x.t" :name="x.k" :autocomplete="x.a" :placeholder="x.p" :aria-invalid="Boolean(form.errors[x.k])" required><span v-if="form.errors[x.k]" role="alert" class="block mt-1 text-red-300">{{form.errors[x.k]}}</span></label><label class="text-[10px] font-semibold text-white/70">Kata sandi (minimal 12 karakter)<input v-model="form.password" type="password" name="password" autocomplete="new-password" minlength="12" placeholder="Minimal 12 karakter" :aria-invalid="Boolean(form.errors.password)" required><span v-if="form.errors.password" role="alert" class="block mt-1 text-red-300">{{form.errors.password}}</span></label><label class="text-[10px] font-semibold text-white/70">Ulangi kata sandi<input v-model="form.password_confirmation" type="password" name="password_confirmation" autocomplete="new-password" placeholder="Masukkan ulang kata sandi" :aria-invalid="Boolean(form.errors.password_confirmation)" required><span v-if="form.errors.password_confirmation" role="alert" class="block mt-1 text-red-300">{{form.errors.password_confirmation}}</span></label><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><p v-if="form.errors.turnstile_token" role="alert" class="text-xs text-red-300">{{form.errors.turnstile_token}}</p><button type="submit" class="lf-primary w-full" :disabled="form.processing">{{form.processing?'Memproses…':'Daftar'}}</button><a href="/auth/google/redirect" class="lf-secondary w-full">Daftar dengan Google</a></div><div class="lf-auth-links justify-end"><Link href="/login">Sudah punya akun? Masuk</Link></div></form></main></CustomerShell></template>